'use client';

import { AnimatePresence } from 'motion/react';

import { cn } from '@/registry/ndeko/lib/utils';
import { Chip } from '@/registry/ndeko/ui/chip';
import { DrawnCheck } from '@/registry/ndeko/ui/drawn-check';

import { FOLDER } from './data';
import { useSteps } from './use-steps';
import { type VisualProps } from './visual-props';

const STEPS = 1 + FOLDER.items.length;

function paperPlaceOf(isOpen: boolean) {
  if (isOpen) {
    return 'translate-y-0';
  }
  return 'translate-y-[20%]';
}

function flapPlaceOf(isOpen: boolean) {
  if (isOpen) {
    return 'translate-y-[115%] opacity-0';
  }
  return 'translate-y-0 opacity-100';
}

function labelToneOf(isTicked: boolean) {
  if (isTicked) {
    return 'text-muted-foreground';
  }
  return 'text-foreground';
}

type CheckItemProps = {
  label: string;
  isTicked: boolean;
  isWorking: boolean;
};

function CheckItem({ label, isTicked, isWorking }: CheckItemProps) {
  return (
    <li className='flex items-center gap-3 py-2'>
      <span className='relative flex size-5 shrink-0 items-center justify-center'>
        <span
          aria-hidden='true'
          className='hairline-ring ring-foreground/25 absolute size-[18px] rounded-full'
        />
        <AnimatePresence initial={false}>
          {isTicked && (
            <DrawnCheck key='tick' tone='success' className='absolute' />
          )}
        </AnimatePresence>
      </span>
      <span
        className={cn(
          'min-w-0 flex-1 text-[13px] transition-colors duration-200',
          labelToneOf(isTicked)
        )}
      >
        {label}
      </span>
      {isWorking && (
        <span
          aria-hidden='true'
          className='bg-primary size-1.5 shrink-0 animate-pulse rounded-full'
        />
      )}
    </li>
  );
}

export function FolderVisual({ progress }: VisualProps) {
  const step = useSteps(progress, STEPS, 0.9);
  const isOpen = step >= 1;
  const ticked = Math.max(0, step - 1);

  return (
    <div className='relative mx-auto aspect-[5/4] w-full max-w-sm'>
      <div
        aria-hidden='true'
        className='bg-foreground/[0.08] absolute inset-x-0 top-7 bottom-0 rounded-2xl'
      />
      <div
        aria-hidden='true'
        className='bg-foreground/[0.08] text-muted-foreground absolute start-0 top-0 flex h-9 w-32 items-center rounded-t-xl px-3 text-xs'
      >
        {FOLDER.name}
      </div>
      <div
        className={cn(
          'bg-card hairline-ring ring-border absolute inset-x-3 top-11 bottom-3 flex flex-col gap-1 rounded-xl p-4 transition-transform duration-700 ease-(--ease-out-strong) motion-reduce:transition-none',
          paperPlaceOf(isOpen)
        )}
      >
        <div className='flex items-center justify-between gap-3'>
          <p className='text-sm font-medium'>Follow-through</p>
          <Chip color='var(--success)'>{FOLDER.status}</Chip>
        </div>
        <ul>
          {FOLDER.items.map((label, index) => (
            <CheckItem
              key={label}
              label={label}
              isTicked={index < ticked}
              isWorking={isOpen && index === ticked}
            />
          ))}
        </ul>
      </div>
      <div
        aria-hidden='true'
        className={cn(
          'bg-card hairline-ring ring-border absolute inset-x-0 bottom-0 z-10 h-[62%] rounded-2xl shadow-[0_-1px_2px_rgb(0_0_0/0.04)] transition-[transform,opacity] duration-700 ease-(--ease-out-strong) motion-reduce:transition-none',
          flapPlaceOf(isOpen)
        )}
      />
    </div>
  );
}

'use client';

import { type MotionValue } from 'motion/react';
import { Fragment } from 'react';

import { leadingSpaceOf, wordsOf } from '@/registry/ndeko/lib/words';
import { cn } from '@/registry/ndeko/lib/utils';

import { useSteps } from './use-steps';

const LIT_BY = 0.7;

function toneOf(isLit: boolean) {
  if (isLit) {
    return 'text-foreground';
  }
  return 'text-foreground/50';
}

type LitCaptionProps = {
  id: string;
  text: string;
  progress: MotionValue<number>;
};

/** Every word is in the page from the start, so it reads whole to anyone who cannot see it light. */
export function LitCaption({ id, text, progress }: LitCaptionProps) {
  const words = wordsOf(text);
  const lit = useSteps(progress, words.length, LIT_BY);

  return (
    <p
      id={id}
      className='text-lg leading-snug font-medium text-pretty sm:text-2xl lg:text-[1.75rem]'
    >
      {words.map((word, index) => (
        <Fragment key={index}>
          {leadingSpaceOf(index)}
          <span
            className={cn(
              'transition-colors duration-300 ease-(--ease-out-strong)',
              toneOf(index < lit)
            )}
          >
            {word}
          </span>
        </Fragment>
      ))}
    </p>
  );
}

'use client';

import { FileTextIcon } from '@/registry/ndeko/lib/icons';
import { cn } from '@/registry/ndeko/lib/utils';
import { Badge } from '@/registry/ndeko/ui/badge';
import { Chip } from '@/registry/ndeko/ui/chip';

import { ILLUSTRATIVE_NOTE, MEMO } from './data';
import { useSteps } from './use-steps';
import { type VisualProps } from './visual-props';

const CHARS_PER_STEP = 2;

const LINE_STARTS = startsOf(MEMO.lines.map((line) => line.text.length));

const TOTAL_CHARS = totalOf(MEMO.lines.map((line) => line.text.length));

const TOTAL_STEPS = Math.ceil(TOTAL_CHARS / CHARS_PER_STEP);

function startsOf(lengths: number[]) {
  const starts: number[] = [];
  let before = 0;
  for (const length of lengths) {
    starts.push(before);
    before += length;
  }
  return starts;
}

function totalOf(lengths: number[]) {
  let total = 0;
  for (const length of lengths) {
    total += length;
  }
  return total;
}

function typedIn(lineIndex: number, typedChars: number) {
  const length = MEMO.lines[lineIndex].text.length;
  const into = typedChars - LINE_STARTS[lineIndex];
  return Math.min(length, Math.max(0, into));
}

function statusClassOf(isComplete: boolean) {
  if (isComplete) {
    return 'opacity-100';
  }
  return 'opacity-0';
}

type MemoLineProps = {
  text: string;
  typed: number;
};

/** The line is a black bar the length of its text, and the text types itself out of the bar from the left. */
function MemoLine({ text, typed }: MemoLineProps) {
  const rest = text.length - typed;
  const barStyle = { width: `${rest}ch` };

  return (
    <p className='font-mono text-[13px] leading-6 whitespace-nowrap'>
      <span className='sr-only'>{text}</span>
      <span aria-hidden='true'>
        {text.slice(0, typed)}
        <span
          style={barStyle}
          className='bg-foreground/85 inline-block h-[0.9em] rounded-[2px] align-[-0.12em]'
        />
      </span>
    </p>
  );
}

export function MemoVisual({ progress }: VisualProps) {
  const step = useSteps(progress, TOTAL_STEPS, 0.88);
  const typedChars = step * CHARS_PER_STEP;
  const isComplete = typedChars >= TOTAL_CHARS;

  return (
    <div className='bg-card hairline-ring ring-border mx-auto flex w-full max-w-md flex-col gap-5 rounded-xl p-5 shadow-[0_1px_2px_rgb(0_0_0/0.04),0_12px_32px_-16px_rgb(0_0_0/0.12)] sm:p-6'>
      <div className='flex items-center gap-2.5'>
        <span className='keycap-3d text-muted-foreground flex size-8 shrink-0 items-center justify-center rounded-lg'>
          <FileTextIcon />
        </span>
        <p className='min-w-0 flex-1 truncate text-sm font-medium'>
          {MEMO.title}
        </p>
        <Badge variant='secondary' className='text-muted-foreground'>
          {ILLUSTRATIVE_NOTE}
        </Badge>
      </div>
      <div className='flex flex-col gap-1.5'>
        {MEMO.lines.map((line, index) => (
          <MemoLine
            key={line.text}
            text={line.text}
            typed={typedIn(index, typedChars)}
          />
        ))}
      </div>
      <div
        aria-live='polite'
        className={cn(
          'transition-opacity duration-300 ease-(--ease-out-strong)',
          statusClassOf(isComplete)
        )}
      >
        <Chip color='var(--success)'>{MEMO.status}</Chip>
      </div>
    </div>
  );
}

'use client';

import { cn } from '@/registry/ndeko/lib/utils';
import { Avatar } from '@/registry/ndeko/ui/avatar';

import { ROLES, type Role } from './data';
import { useSteps } from './use-steps';
import { type VisualProps } from './visual-props';

function rowToneOf(isForward: boolean, isCurrent: boolean) {
  if (isCurrent) {
    return 'bg-card hairline-ring ring-border shadow-[0_1px_2px_rgb(0_0_0/0.04),0_12px_32px_-16px_rgb(0_0_0/0.12)]';
  }
  if (isForward) {
    return 'opacity-100';
  }
  return 'scale-[0.97] opacity-35';
}

function decisionRowsOf(isCurrent: boolean) {
  if (isCurrent) {
    return 'grid-rows-[1fr]';
  }
  return 'grid-rows-[0fr]';
}

type RoleRowProps = {
  role: Role;
  isForward: boolean;
  isCurrent: boolean;
};

function RoleRow({ role, isForward, isCurrent }: RoleRowProps) {
  return (
    <li
      className={cn(
        'rounded-xl transition-[opacity,scale,background-color,box-shadow] duration-300 ease-(--ease-out-strong) motion-reduce:transition-none',
        rowToneOf(isForward, isCurrent)
      )}
    >
      <div className='flex items-center gap-3 p-3'>
        <Avatar
          className='size-8'
          seed={role.name}
          role='img'
          aria-label={role.name}
        />
        <div className='flex min-w-0 flex-col'>
          <p className='truncate text-[13px] font-medium'>{role.name}</p>
          <p className='text-muted-foreground truncate text-xs'>{role.role}</p>
        </div>
      </div>
      <div
        className={cn(
          'grid transition-[grid-template-rows] duration-300 ease-(--ease-out-strong) motion-reduce:transition-none',
          decisionRowsOf(isCurrent)
        )}
      >
        <div className='overflow-hidden'>
          <p className='px-3 ps-14 pb-3 text-[13px] text-pretty'>
            {role.decision}
          </p>
        </div>
      </div>
    </li>
  );
}

export function RolesVisual({ progress }: VisualProps) {
  const forward = useSteps(progress, ROLES.length, 0.9);

  return (
    <ul className='mx-auto flex w-full max-w-md flex-col gap-1.5'>
      {ROLES.map((role, index) => (
        <RoleRow
          key={role.name}
          role={role}
          isForward={index < forward}
          isCurrent={index === forward - 1}
        />
      ))}
    </ul>
  );
}

